                checkmarkColor = NoteTheme.OnPrimary
            ),
            modifier = Modifier.size(24.dp)
        )

        Spacer(modifier = Modifier.width(8.dp))

        // Text field
        if (readOnly) {
            Text(
                text = item.text.ifEmpty { " " },
                style = MaterialTheme.typography.bodyLarge.copy(
                    textDecoration = if (item.isChecked) TextDecoration.LineThrough else TextDecoration.None
                ),
                color = textColor,
                modifier = Modifier.weight(1f)
            )
        } else {
            BasicTextField(
                value = item.text,
                onValueChange = onTextChange,
                modifier = Modifier
                    .weight(1f)
                    .focusRequester(focusRequester)
                    .onKeyEvent { event ->
                        if (event.key == Key.Backspace && item.text.isEmpty()) {
                            onBackspaceOnEmpty()
                            true
                        } else {
                            false
                        }
                    },
                textStyle = TextStyle(
                    color = textColor,
                    fontSize = MaterialTheme.typography.bodyLarge.fontSize,
                    textDecoration = if (item.isChecked) TextDecoration.LineThrough else TextDecoration.None
                ),
                cursorBrush = SolidColor(NoteTheme.Primary),
                singleLine = true,
                keyboardOptions = KeyboardOptions(imeAction = ImeAction.Next),
                keyboardActions = KeyboardActions(
                    onNext = { onEnterPressed() }
                ),
                decorationBox = { innerTextField ->
                    Box {
                        if (item.text.isEmpty()) {
                            Text(
                                "Add item...",
                                style = MaterialTheme.typography.bodyLarge,
                                color = NoteTheme.OnSurfaceVariant.copy(alpha = 0.4f)
                            )
                        }
                        innerTextField()
                    }
                }
            )
        }

        // Delete button (editor only)
        if (!readOnly) {
            IconButton(
                onClick = onDelete,
                modifier = Modifier.size(28.dp)
            ) {
                Icon(
                    Icons.Outlined.Close,
                    contentDescription = "Remove item",
                    tint = NoteTheme.OnSurfaceVariant.copy(alpha = 0.4f),
                    modifier = Modifier.size(16.dp)
                )
            }
        }
    }
}

/**
 * Progress bar display for checklist notes in list cards.
 */
@Composable
fun ChecklistProgressIndicator(
    checked: Int,
    total: Int,
    modifier: Modifier = Modifier
) {
    if (total <= 0) return

    val fraction = checked.toFloat() / total.toFloat()
    val progressColor by animateColorAsState(
        targetValue = if (fraction >= 1f) NoteTheme.Primary
        else NoteTheme.Secondary,
        animationSpec = tween(300),
        label = "progress_color"
    )

    Row(
        modifier = modifier.fillMaxWidth(),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        // Progress bar
        Box(
            modifier = Modifier
                .weight(1f)
                .size(height = 4.dp, width = 0.dp)
                .clip(RoundedCornerShape(2.dp))
                .background(NoteTheme.OnSurfaceVariant.copy(alpha = 0.1f))
        ) {
            Box(
                modifier = Modifier
                    .fillMaxWidth(fraction)
                    .size(height = 4.dp, width = 0.dp)
                    .clip(RoundedCornerShape(2.dp))
                    .background(progressColor)
            )
        }

        // Count text
        Text(
            text = "$checked/$total",
            style = MaterialTheme.typography.labelSmall,
            color = progressColor
        )
    }
}

package com.amvarpvtltd.swiftNote.viewmodel

import android.app.Application
import android.util.Log
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.amvarpvtltd.swiftNote.auth.DeviceManager
import com.amvarpvtltd.swiftNote.auth.PassphraseManager
