import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

/**
 * ViewModel for the Notes list screen.
 * Uses Flow-based reactive observation from Room (Phase 0).
 * Supports undo-delete via pendingDelete state (Phase 0).
 */
class NotesViewModel(application: Application) : AndroidViewModel(application) {

    private val TAG = "NotesViewModel"
    private val context = application.applicationContext

    val noteRepository = NoteRepository.getInstance(context)
    val networkManager = NetworkManager.getInstance(context)
    val autoSyncManager = AutoSyncManager.getInstance(context, noteRepository)

    // Phase 0.3: Flow-based reactive notes from Room — auto-updates on DB changes
    val notes: StateFlow<List<dataclass>> = noteRepository.observeNotes()
        .catch { e ->
            Log.e(TAG, "Error observing notes", e)
            emit(emptyList())
        }
        .stateIn(
            scope = viewModelScope,
            started = SharingStarted.WhileSubscribed(5000),
            initialValue = emptyList()
        )

    private val _isLoading = MutableStateFlow(true)
    val isLoading: StateFlow<Boolean> = _isLoading.asStateFlow()

    private val _isRefreshing = MutableStateFlow(false)
    val isRefreshing: StateFlow<Boolean> = _isRefreshing.asStateFlow()

    // Phase 0.4: Undo-delete support
    private val _pendingDelete = MutableStateFlow<dataclass?>(null)
    val pendingDelete: StateFlow<dataclass?> = _pendingDelete.asStateFlow()
    private var undoDeleteJob: Job? = null

    // One-shot UI events (toasts, navigation) — collected once, never replayed
    private val _uiEvent = MutableSharedFlow<UiEvent>()
    val uiEvent: SharedFlow<UiEvent> = _uiEvent.asSharedFlow()

    sealed class UiEvent {
        data class ShowToast(val message: String) : UiEvent()
        object NavigateToMain : UiEvent()
    }

    init {
        // Initial data load for first-time display + mark loading complete
        viewModelScope.launch {
            // Small delay to allow Flow to emit first value
            delay(Constants.LOADING_DELAY)
            _isLoading.value = false
        }
        startAutoSync()
        attemptOneTimeRemoteImport()
    }

    /**
     * Manually refresh notes from the repository (triggers background cloud sync).
     * The Flow will automatically pick up any changes written to the DB.
     */
    fun refreshNotes() {
        viewModelScope.launch {
            _isRefreshing.value = true
            try {
                // Trigger a fetch which syncs from cloud to local DB
                withContext(Dispatchers.IO) { noteRepository.fetchNotes() }
            } finally {
                _isRefreshing.value = false
            }
        }
    }

    /**
     * Phase 0.4: Delete with undo support.
     * Holds the note for 4 seconds before permanent deletion.
     */
    fun deleteNote(noteId: String) {
        // Find the note in current list to hold for undo
        val noteToDelete = notes.value.find { it.id == noteId }

        viewModelScope.launch(Dispatchers.IO) {
            try {
                val result = noteRepository.deleteNote(noteId, context)
                if (result.isSuccess) {
                    if (noteToDelete != null) {
                        // Set pending delete for undo
                        _pendingDelete.value = noteToDelete
                        // Cancel any previous undo timer
                        undoDeleteJob?.cancel()
                        // Start timer to clear pending state
                        undoDeleteJob = viewModelScope.launch {
                            delay(4000L) // 4 second undo window
                            _pendingDelete.value = null
                        }
                    }
                    if (!networkManager.isConnected()) {
                        _uiEvent.emit(UiEvent.ShowToast(" Note deleted offline. Will sync when online."))
                    }
                }
            } catch (e: Exception) {
                _uiEvent.emit(UiEvent.ShowToast(Constants.ERROR_DELETING_MESSAGE))
            }
        }
    }

    /**
     * Phase 0.4: Undo the last delete.
     * Re-saves the note that was pending deletion.
     */
    fun undoDelete() {
        val note = _pendingDelete.value ?: return
        undoDeleteJob?.cancel()
        _pendingDelete.value = null

        viewModelScope.launch(Dispatchers.IO) {
            try {
                noteRepository.saveNote(
                    title = note.title,
                    description = note.description,
                    noteId = note.id,
                    context = context
                )
            } catch (e: Exception) {
                Log.e(TAG, "Failed to undo delete", e)
                _uiEvent.emit(UiEvent.ShowToast("❌ Failed to restore note"))
            }
        }
    }

    fun syncNotes() {
        if (!networkManager.isConnected()) {
            viewModelScope.launch { _uiEvent.emit(UiEvent.ShowToast("❌ Can't sync while offline")) }
            return
        }

        viewModelScope.launch(Dispatchers.IO) {
            try {
                val result = noteRepository.syncOfflineNotes(context)
                if (result.isSuccess) {
                    _uiEvent.emit(UiEvent.ShowToast("✅ Sync completed"))
                }
            } catch (e: Exception) {
                _uiEvent.emit(UiEvent.ShowToast("❌ Sync failed"))
            }
        }
    }

    private fun startAutoSync() {
        autoSyncManager.startAutoSync()
    }

    fun stopAutoSync() {
        autoSyncManager.stopAutoSync()
    }

    private fun attemptOneTimeRemoteImport() {
        if (!networkManager.isConnected()) return
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val accountId = PassphraseManager.getStoredPassphrase(context)
                    ?: DeviceManager.getOrCreateDeviceId(context)
                val res = SyncManager.syncDataFromPassphrase(context, accountId, accountId)
                if (res.isSuccess) {
                    // Flow will auto-update, no manual refresh needed
                    Log.d(TAG, "One-time remote import succeeded")
                } else {
                    Log.d(TAG, "One-time remote import failed: ${res.exceptionOrNull()?.message}")
                }
            } catch (e: Exception) {
                Log.d(TAG, "One-time remote import failed", e)
            }
        }
    }

    override fun onCleared() {
        super.onCleared()
        autoSyncManager.stopAutoSync()
    }
}

package com.amvarpvtltd.swiftNote.viewmodel

import android.app.Application
import android.util.Log
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.amvarpvtltd.swiftNote.auth.DeviceManager
import com.amvarpvtltd.swiftNote.auth.PassphraseManager
import com.amvarpvtltd.swiftNote.dataclass
import com.amvarpvtltd.swiftNote.repository.NoteRepository
import com.amvarpvtltd.swiftNote.sync.SyncManager
import com.amvarpvtltd.swiftNote.utils.AutoSyncManager
import com.amvarpvtltd.swiftNote.utils.Constants
import com.amvarpvtltd.swiftNote.utils.NetworkManager
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

/**
 * ViewModel for the Notes list screen.
 * Uses Flow-based reactive observation from Room (Phase 0).
 * Supports undo-delete via pendingDelete state (Phase 0).
 */
class NotesViewModel(application: Application) : AndroidViewModel(application) {

    private val TAG = "NotesViewModel"
    private val context = application.applicationContext

    val noteRepository = NoteRepository.getInstance(context)
    val networkManager = NetworkManager.getInstance(context)
    val autoSyncManager = AutoSyncManager.getInstance(context, noteRepository)

    // Phase 0.3: Flow-based reactive notes from Room — always active (Eagerly) so cached
    // data is available instantly on navigation back without Room requery lag
    val notes: StateFlow<List<dataclass>> = noteRepository.observeNotes()
        .catch { e ->
            Log.e(TAG, "Error observing notes", e)
            emit(emptyList())
        }
        .stateIn(
            scope = viewModelScope,
            started = SharingStarted.Eagerly, // never stops — keeps data hot for instant nav-back
            initialValue = emptyList()
        )

    private val _isLoading = MutableStateFlow(true)
    val isLoading: StateFlow<Boolean> = _isLoading.asStateFlow()

    private val _isRefreshing = MutableStateFlow(false)
    val isRefreshing: StateFlow<Boolean> = _isRefreshing.asStateFlow()

    // Phase 0.4: Undo-delete support
    private val _pendingDelete = MutableStateFlow<dataclass?>(null)
    val pendingDelete: StateFlow<dataclass?> = _pendingDelete.asStateFlow()
    private var undoDeleteJob: Job? = null

    // One-shot UI events (toasts, navigation) — collected once, never replayed
    private val _uiEvent = MutableSharedFlow<UiEvent>()
    val uiEvent: SharedFlow<UiEvent> = _uiEvent.asSharedFlow()

    sealed class UiEvent {
        data class ShowToast(val message: String) : UiEvent()
        object NavigateToMain : UiEvent()
    }

    init {
        // Initial data load for first-time display + mark loading complete
        viewModelScope.launch {
            // Small delay to allow Flow to emit first value
            delay(Constants.LOADING_DELAY)
            _isLoading.value = false
        }
        startAutoSync()
        attemptOneTimeRemoteImport()
    }

    /**
     * Manually refresh notes from the repository (triggers background cloud sync).
     * The Flow will automatically pick up any changes written to the DB.
     */
    fun refreshNotes() {
        viewModelScope.launch {
            _isRefreshing.value = true
            try {
                // Trigger a fetch which syncs from cloud to local DB
                withContext(Dispatchers.IO) { noteRepository.fetchNotes() }
            } finally {
                _isRefreshing.value = false
            }
        }
    }

    /**
     * Phase 0.4: Delete with undo support.
     * Holds the note for 4 seconds before permanent deletion.
     */
    fun deleteNote(noteId: String) {
        // Find the note in current list to hold for undo
        val noteToDelete = notes.value.find { it.id == noteId }

        viewModelScope.launch(Dispatchers.IO) {
            try {
                val result = noteRepository.deleteNote(noteId, context)
                if (result.isSuccess) {
                    if (noteToDelete != null) {
                        // Set pending delete for undo
                        _pendingDelete.value = noteToDelete
                        // Cancel any previous undo timer
                        undoDeleteJob?.cancel()
                        // Start timer to clear pending state
                        undoDeleteJob = viewModelScope.launch {
                            delay(4000L) // 4 second undo window
                            _pendingDelete.value = null
                        }
                    }
                    if (!networkManager.isConnected()) {
                        _uiEvent.emit(UiEvent.ShowToast(" Note deleted offline. Will sync when online."))
                    }
                }
            } catch (e: Exception) {
                _uiEvent.emit(UiEvent.ShowToast(Constants.ERROR_DELETING_MESSAGE))
            }
        }
    }

    /**
     * Phase 0.4: Undo the last delete.
     * Re-saves the note that was pending deletion.
     */
    fun undoDelete() {
        val note = _pendingDelete.value ?: return
        undoDeleteJob?.cancel()
        _pendingDelete.value = null

        viewModelScope.launch(Dispatchers.IO) {
            try {
                noteRepository.saveNote(
                    title = note.title,
                    description = note.description,
                    noteId = note.id,
                    context = context
                )
            } catch (e: Exception) {
                Log.e(TAG, "Failed to undo delete", e)
                _uiEvent.emit(UiEvent.ShowToast("❌ Failed to restore note"))
            }
        }
    }

    fun syncNotes() {
        if (!networkManager.isConnected()) {
            viewModelScope.launch { _uiEvent.emit(UiEvent.ShowToast("❌ Can't sync while offline")) }
            return
        }

        viewModelScope.launch(Dispatchers.IO) {
            try {
                val result = noteRepository.syncOfflineNotes(context)
                if (result.isSuccess) {
                    _uiEvent.emit(UiEvent.ShowToast("✅ Sync completed"))
                }
            } catch (e: Exception) {
                _uiEvent.emit(UiEvent.ShowToast("❌ Sync failed"))
            }
        }
    }

    private fun startAutoSync() {
        autoSyncManager.startAutoSync()
    }

    fun stopAutoSync() {
        autoSyncManager.stopAutoSync()
    }

    private fun attemptOneTimeRemoteImport() {
        if (!networkManager.isConnected()) return
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val accountId = PassphraseManager.getStoredPassphrase(context)
                    ?: DeviceManager.getOrCreateDeviceId(context)
                val res = SyncManager.syncDataFromPassphrase(context, accountId, accountId)
                if (res.isSuccess) {
                    // Flow will auto-update, no manual refresh needed
                    Log.d(TAG, "One-time remote import succeeded")
                } else {
                    Log.d(TAG, "One-time remote import failed: ${res.exceptionOrNull()?.message}")
                }
            } catch (e: Exception) {
                Log.d(TAG, "One-time remote import failed", e)
            }
        }
    }

    override fun onCleared() {
        super.onCleared()
        autoSyncManager.stopAutoSync()
    }
}

package com.amvarpvtltd.swiftNote.offline

import android.content.Context
import androidx.room.Room
import com.amvarpvtltd.swiftNote.Note
import com.amvarpvtltd.swiftNote.myGlobalMobileDeviceId
import com.amvarpvtltd.swiftNote.room.AppDatabase
import com.amvarpvtltd.swiftNote.room.NoteEntity
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.test.runTest
import org.junit.After
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config

/**
 * Unit tests for OfflineNoteManager covering:
 * - BUG-014: Init doesn't leak coroutines
 * - BUG-039: Delete + pending deletion is atomic
 * - Basic CRUD operations
 */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [31], manifest = Config.NONE)
@OptIn(ExperimentalCoroutinesApi::class)
class OfflineNoteManagerTest {

    private lateinit var context: Context
    private lateinit var manager: OfflineNoteManager

    @Before
    fun setUp() {
        context = RuntimeEnvironment.getApplication()
        myGlobalMobileDeviceId = "test-device-offline"
        manager = OfflineNoteManager(context)
    }

    @After
    fun tearDown() {
        manager.close()
    }

    // ============================================================
    // Save Tests
    // ============================================================

    @Test
    fun `saveNoteOffline returns success`() = runTest {
        val note = Note(title = "Test Note", description = "Test Description", mymobiledeviceid = "test-device-offline")
        val result = manager.saveNoteOffline(note)
        assertTrue(result.isSuccess)
    }

    @Test
    fun `saved note can be retrieved by ID`() = runTest {
        val note = Note(title = "Findable", description = "Description", id = "find-me", mymobiledeviceid = "test-device-offline")
        manager.saveNoteOffline(note)
        val retrieved = manager.getNoteById("find-me")
        assertNotNull(retrieved)
        assertEquals("find-me", retrieved!!.id)
    }

    @Test
    fun `getAllNotes returns saved notes`() = runTest {
        val note1 = Note(title = "Note 1", description = "Desc 1", id = "id-1", mymobiledeviceid = "test-device-offline")
        val note2 = Note(title = "Note 2", description = "Desc 2", id = "id-2", mymobiledeviceid = "test-device-offline")
        manager.saveNoteOffline(note1)
        manager.saveNoteOffline(note2)

        val all = manager.getAllNotes()
        assertTrue(all.size >= 2)
    }

    // ============================================================
    // Delete Tests (BUG-039: Atomic delete + pending)
    // ============================================================

    @Test
    fun `deleteNoteOffline removes note from local storage`() = runTest {
        val note = Note(title = "Delete Me", description = "Desc", id = "del-1", mymobiledeviceid = "test-device-offline")
        manager.saveNoteOffline(note)

        val result = manager.deleteNoteOffline("del-1")
        assertTrue(result.isSuccess)

        val retrieved = manager.getNoteById("del-1")
        assertNull(retrieved)
    }

    @Test
    fun `deleteNoteOffline records pending deletion for sync`() = runTest {
        val note = Note(title = "Delete Me", description = "Desc", id = "del-2", mymobiledeviceid = "test-device-offline")
        manager.saveNoteOffline(note)
        manager.deleteNoteOffline("del-2")

        val pendingDeletions = manager.getPendingDeletions()
        assertTrue(pendingDeletions.any { it.noteId == "del-2" })
    }

    @Test
    fun `deleteNoteOffline for non-existent note returns success`() = runTest {
        val result = manager.deleteNoteOffline("non-existent-id")
        assertTrue(result.isSuccess) // Should not crash
    }

    // ============================================================
    // Sync State Tests
    // ============================================================

    @Test
    fun `saveNoteOffline with synced false creates pending sync`() = runTest {
        val note = Note(title = "Pending", description = "Desc", id = "pending-1", mymobiledeviceid = "test-device-offline")
        manager.saveNoteOffline(note, synced = false)

        val pending = manager.getPendingSyncNotes()
        assertTrue(pending.any { it.id == "pending-1" })
    }

    @Test
    fun `saveNoteOffline with synced true does not create pending sync`() = runTest {
        val note = Note(title = "Synced", description = "Desc", id = "synced-1", mymobiledeviceid = "test-device-offline")
        manager.saveNoteOffline(note, synced = true)

        val pending = manager.getPendingSyncNotes()
        assertFalse(pending.any { it.id == "synced-1" })
    }

    @Test
    fun `markNoteAsSynced removes from pending`() = runTest {
        val note = Note(title = "Mark", description = "Desc", id = "mark-1", mymobiledeviceid = "test-device-offline")
        manager.saveNoteOffline(note, synced = false)

        assertTrue(manager.getPendingSyncNotes().any { it.id == "mark-1" })

        manager.markNoteAsSynced("mark-1")

        assertFalse(manager.getPendingSyncNotes().any { it.id == "mark-1" })
    }

    // ============================================================
    // BUG-014: Close/Lifecycle Tests
    // ============================================================

    @Test
    fun `close does not throw`() {
        val mgr = OfflineNoteManager(context)
        mgr.close() // Should not throw
    }

    @Test
    fun `hasPendingSync reflects state correctly`() = runTest {
        // Initially no pending
        val freshManager = OfflineNoteManager(context)
        // Give init time to complete
        kotlinx.coroutines.delay(100)
        // hasPendingSync depends on stateflow — may be empty on fresh DB
        assertNotNull(freshManager.hasPendingSync())
        freshManager.close()
    }
}

package com.amvarpvtltd.swiftNote.offline

import com.amvarpvtltd.swiftNote.Note
import com.amvarpvtltd.swiftNote.myGlobalMobileDeviceId
import com.amvarpvtltd.swiftNote.room.NoteEntity
import com.amvarpvtltd.swiftNote.room.NoteEntityMapper
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

/**
 * Unit tests for OfflineNoteManager's non-DB logic:
 * - NoteEntityMapper bidirectional mapping
 * - BUG-039: Transaction-based delete logic is tested via instrumented tests
 */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [31], manifest = Config.NONE)
class OfflineNoteManagerTest {

    @Before
    fun setUp() {
        myGlobalMobileDeviceId = "test-device-offline"
    }

    // ============================================================
    // NoteEntityMapper Tests
    // ============================================================

    @Test
    fun `toEntity maps Note fields correctly`() {
        val note = Note(
            title = "Test Title",
            description = "Test Description",
            id = "note-123",
            mymobiledeviceid = "device-456",
            timestamp = 1000L
        )
        val entity = NoteEntityMapper.toEntity(note, synced = false)
        assertEquals("note-123", entity.id)
        assertEquals("device-456", entity.mymobiledeviceid)
        assertEquals(1000L, entity.timestamp)
        assertFalse(entity.synced)
        // Title and description should be encrypted (non-empty, different from plain)
        assertTrue(entity.title.isNotEmpty())
        assertTrue(entity.description.isNotEmpty())
    }

    @Test
    fun `toEntity with synced true sets synced flag`() {
        val note = Note(
            title = "Title",
            description = "Desc",
            id = "id-1",
            mymobiledeviceid = "device-1",
            timestamp = 2000L
        )
        val entity = NoteEntityMapper.toEntity(note, synced = true)
        assertTrue(entity.synced)
    }

    @Test
    fun `toDomain maps NoteEntity back to Note`() {
        // Create an entity with encrypted data
        val note = Note(
            title = "Original Title",
            description = "Original Desc",
            id = "id-2",
            mymobiledeviceid = "test-device-offline",
            timestamp = 3000L
        )
        val entity = NoteEntityMapper.toEntity(note, synced = true)

        // Map back to domain
        val restored = NoteEntityMapper.toDomain(entity)
        assertEquals("id-2", restored.id)
        assertEquals("test-device-offline", restored.mymobiledeviceid)
        assertEquals(3000L, restored.timestamp)
        // Title/desc should be decrypted back to original
        assertEquals("Original Title", restored.title)
        assertEquals("Original Desc", restored.description)
    }

    @Test
    fun `roundtrip Note to Entity to Note preserves data`() {
        val original = Note(
            title = "Roundtrip Test",
            description = "This is a roundtrip test with special chars: <b>bold</b>",
            id = "rt-1",
            mymobiledeviceid = "test-device-offline",
            timestamp = 4000L
        )
        val entity = NoteEntityMapper.toEntity(original, synced = false)
        val restored = NoteEntityMapper.toDomain(entity)

        assertEquals(original.title, restored.title)
        assertEquals(original.description, restored.description)
        assertEquals(original.id, restored.id)
        assertEquals(original.mymobiledeviceid, restored.mymobiledeviceid)
        assertEquals(original.timestamp, restored.timestamp)
    }

    @Test
    fun `toDomain handles empty title and description`() {
        val entity = NoteEntity(
            id = "empty-1",
            title = "",
            description = "",
            mymobiledeviceid = "test-device-offline",
            timestamp = 5000L,
            synced = true
        )
        val note = NoteEntityMapper.toDomain(entity)
        assertEquals("", note.title)
        assertEquals("", note.description)
    }
}

package com.amvarpvtltd.swiftNote.reminders

import android.Manifest
import android.annotation.SuppressLint
import android.app.AlarmManager
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.os.Build
import android.util.Log
import androidx.annotation.RequiresPermission
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import com.amvarpvtltd.swiftNote.MainActivity
import com.amvarpvtltd.swiftNote.R
import com.amvarpvtltd.swiftNote.ai.DetectedReminder
import com.amvarpvtltd.swiftNote.room.AppDatabase
import kotlinx.coroutines.CoroutineExceptionHandler
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * Manages reminders with persistent alarms that survive device reboots
 */
class ReminderManager private constructor(private val context: Context) {
    private val TAG = "ReminderManager"

    private val alarmManager = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager
    private val database = AppDatabase.getInstance(context)
    private val reminderDao = database.reminderDao()

    private val exceptionHandler = CoroutineExceptionHandler { _, exception ->
        Log.e(TAG, "Uncaught exception in ReminderManager scope", exception)
    }
    private val managerScope = CoroutineScope(Dispatchers.IO + SupervisorJob() + exceptionHandler)

    companion object {
        @SuppressLint("StaticFieldLeak")
        @Volatile
        private var INSTANCE: ReminderManager? = null

        private const val NOTIFICATION_CHANNEL_ID = "smart_reminders"
        private const val NOTIFICATION_CHANNEL_NAME = "Smart Reminders"

        const val EXTRA_REMINDER_ID = "reminder_id"
        const val EXTRA_REMINDER_TITLE = "reminder_title"
        const val EXTRA_REMINDER_DESCRIPTION = "reminder_description"
        const val EXTRA_NOTE_ID = "note_id"

        fun getInstance(context: Context): ReminderManager {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: ReminderManager(context.applicationContext).also {
                    INSTANCE = it
                    it.createNotificationChannel()
                }
            }
        }
    }

    /**
     * Create notification channel for reminders
     */
    private fun createNotificationChannel() {
        val channel = NotificationChannel(
            NOTIFICATION_CHANNEL_ID,
            NOTIFICATION_CHANNEL_NAME,
            NotificationManager.IMPORTANCE_HIGH
        ).apply {
            description = "Notifications for smart reminders from your notes"
            enableVibration(true)
            enableLights(true)
            setShowBadge(true)
        }

        val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        notificationManager.createNotificationChannel(channel)
        Log.d(TAG, " Notification channel created")
    }

    /**
     * Schedule a reminder alarm
     */
    suspend fun scheduleReminder(
        reminder: DetectedReminder,
        noteId: String
    ): Result<String> = withContext(Dispatchers.IO) {
        return@withContext try {
            // Check if we can schedule exact alarms
            if (!canScheduleExactAlarms()) {
                // Don't fail hard if exact alarm permission isn't granted. Persist the reminder
                // and schedule a best-effort alarm. This ensures reminders are created even when
                // the system restricts exact alarms (app may request permission separately).
                Log.w(TAG, "⚠️ Exact alarm permission not granted — falling back to best-effort scheduling")
            }

            // Save reminder to database - Fixed field names to match ReminderEntity
            val reminderEntity = ReminderEntity(
                id = reminder.id,
                noteId = noteId,
                noteTitle = reminder.title,
                noteDescription = reminder.description,
                reminderTime = reminder.reminderDateTime,
                isActive = true,
                createdAt = System.currentTimeMillis()
            )

            reminderDao.insertReminder(reminderEntity) // Fixed method name
            Log.d(TAG, " Reminder saved to database: ${reminder.title}")

            // Schedule the alarm
            val intent = Intent(context, ReminderReceiver::class.java).apply {
                putExtra(EXTRA_REMINDER_ID, reminder.id)
                putExtra(EXTRA_REMINDER_TITLE, reminder.title)
                putExtra(EXTRA_REMINDER_DESCRIPTION, reminder.description)
                putExtra(EXTRA_NOTE_ID, noteId)
            }

            val pendingIntent = PendingIntent.getBroadcast(
                context,
                reminder.id.hashCode(),
                intent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )

            // Schedule exact alarm if possible, otherwise schedule a best-effort alarm
            try {
                if (canScheduleExactAlarms()) {
                    alarmManager.setExactAndAllowWhileIdle(
                        AlarmManager.RTC_WAKEUP,
                        reminder.reminderDateTime,
                        pendingIntent
                    )
                } else {
                    // Best-effort fallback using set which may be inexact but still fires
                    alarmManager.set(
                        AlarmManager.RTC_WAKEUP,
                        reminder.reminderDateTime,
                        pendingIntent
                    )
                }
            } catch (e: SecurityException) {
                Log.w(TAG, "⚠️ SecurityException scheduling alarm, skipping alarm scheduling: ${e.message}")
            }

            val formatter = SimpleDateFormat("MMM dd, yyyy 'at' hh:mm a", Locale.getDefault())
            val dateTime = formatter.format(Date(reminder.reminderDateTime))

            Log.d(TAG, "⏰ Reminder scheduled: ${reminder.title} for $dateTime")
            Result.success("Reminder scheduled for $dateTime")

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error scheduling reminder", e)
            Result.failure(e)
        }
    }

    /**
     * Get all active reminders
     */
    suspend fun getAllActiveReminders(): List<ReminderEntity> = withContext(Dispatchers.IO) {
        return@withContext try {
            reminderDao.getAllActiveReminders().first()
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error getting all active reminders", e)
            emptyList()
        }
    }

    /**
     * Reschedule all active reminders (called after device reboot)
     */
    suspend fun rescheduleAllReminders(): Result<String> = withContext(Dispatchers.IO) {
        return@withContext try {
            val activeReminders = getAllActiveReminders() // Use the corrected method
            val currentTime = System.currentTimeMillis()
            var rescheduledCount = 0

            activeReminders.forEach { reminder ->
                if (reminder.reminderTime > currentTime) { // Fixed field name
                    // Reschedule future reminders
                    val intent = Intent(context, ReminderReceiver::class.java).apply {
                        putExtra(EXTRA_REMINDER_ID, reminder.id)
                        putExtra(EXTRA_REMINDER_TITLE, reminder.noteTitle) // Fixed field name
                        putExtra(EXTRA_REMINDER_DESCRIPTION, reminder.noteDescription) // Fixed field name
                        putExtra(EXTRA_NOTE_ID, reminder.noteId)
                    }

                    val pendingIntent = PendingIntent.getBroadcast(
                        context,
                        reminder.id.hashCode(),
                        intent,
                        PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                    )

                    // Schedule exact alarm if possible, otherwise use best-effort fallback
                    try {
                        if (canScheduleExactAlarms()) {
                            alarmManager.setExactAndAllowWhileIdle(
                                AlarmManager.RTC_WAKEUP,
                                reminder.reminderTime,
                                pendingIntent
                            )
                        } else {
                            alarmManager.set(
                                AlarmManager.RTC_WAKEUP,
                                reminder.reminderTime,
                                pendingIntent
                            )
                        }
                    } catch (e: SecurityException) {
                        Log.w(TAG, "⚠️ SecurityException rescheduling alarm for ${reminder.id}: ${e.message}")
                        // Best-effort fallback
                        alarmManager.set(
                            AlarmManager.RTC_WAKEUP,
                            reminder.reminderTime,
                            pendingIntent
                        )
                    }
                    rescheduledCount++
                } else {
                    // Mark expired reminders as inactive - Fixed using deactivateReminder
                    reminderDao.deactivateReminder(reminder.id)
                }
            }

            Log.d(TAG, " Rescheduled $rescheduledCount reminders after reboot")
            Result.success("Rescheduled $rescheduledCount reminders")

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error rescheduling reminders", e)
            Result.failure(e)
        }
    }

    /**
     * Create a reminder from AI detection
     * This is a convenience method that wraps scheduleReminder with proper error handling
     */
    suspend fun createReminderFromDetection(
        detectedReminder: DetectedReminder,
        noteId: String
    ): Boolean {
        return try {
            val result = scheduleReminder(detectedReminder, noteId)
            result.isSuccess
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error creating reminder from detection", e)
            false
        }
    }

    /**
     * Check if the app can schedule exact alarms
     */
    fun canScheduleExactAlarms(): Boolean {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            alarmManager.canScheduleExactAlarms()
        } else {
            true
        }
    }

    /**
     * Open system settings to allow the user to grant exact alarm permission (Android 12+).
     * Returns true if the intent was launched, false if not needed or not applicable.
     */
    fun requestExactAlarmPermission(): Boolean {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S && !canScheduleExactAlarms()) {
            try {
                val intent = Intent(
                    android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,
                    android.net.Uri.parse("package:${context.packageName}")
                ).apply {
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                }
                context.startActivity(intent)
                return true
            } catch (e: Exception) {
                Log.e(TAG, "❌ Error opening exact alarm settings", e)
            }
        }
        return false
    }

    /**
     * Show notification for triggered reminder
     */
    fun showReminderNotification(
        reminderId: String,
        title: String,
        description: String,
        noteId: String
    ) {
        try {
            // Check notification permissions first
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                val notificationManager = NotificationManagerCompat.from(context)
                if (!notificationManager.areNotificationsEnabled()) {
                    Log.w(TAG, "⚠️ Notifications are disabled for this app")
                    return
                }
            }

            // Create intent to open the note
            val notificationIntent = Intent(context, MainActivity::class.java).apply {
                putExtra("noteId", noteId)
                flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
            }

            val pendingIntent = PendingIntent.getActivity(
                context,
                reminderId.hashCode(),
                notificationIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )

            val notification = NotificationCompat.Builder(context, NOTIFICATION_CHANNEL_ID)
                .setSmallIcon( R.drawable.logo2)
                .setContentTitle(" $title")
                .setContentText(description)
                .setPriority(NotificationCompat.PRIORITY_HIGH)
                .setCategory(NotificationCompat.CATEGORY_REMINDER)
                .setAutoCancel(true)
                .setContentIntent(pendingIntent)
                .setVibrate(longArrayOf(0, 500, 100, 500))
                .setDefaults(NotificationCompat.DEFAULT_SOUND or NotificationCompat.DEFAULT_LIGHTS)
                .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
                .setOnlyAlertOnce(false)
                .build()

            val notificationManager = NotificationManagerCompat.from(context)
            try {
                notificationManager.notify(reminderId.hashCode(), notification)
                Log.d(TAG, " Reminder notification shown: $title")

                // Mark reminder as completed in database - Fixed using deactivateReminder
                managerScope.launch {
                    try {
                        reminderDao.deactivateReminder(reminderId)
                        Log.d(TAG, "✅ Reminder marked as completed: $title")
                    } catch (e: Exception) {
                        Log.e(TAG, "❌ Error marking reminder as completed", e)
                    }
                }
            } catch (e: SecurityException) {
                Log.e(TAG, "❌ Missing notification permission", e)
            }

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error showing reminder notification", e)
        }
    }
}

/**
 * BroadcastReceiver to handle reminder alarms
 */
class ReminderReceiver : BroadcastReceiver() {
    @RequiresPermission(Manifest.permission.POST_NOTIFICATIONS)
    override fun onReceive(context: Context, intent: Intent) {
        val reminderId = intent.getStringExtra(ReminderManager.EXTRA_REMINDER_ID) ?: return
        val title = intent.getStringExtra(ReminderManager.EXTRA_REMINDER_TITLE) ?: "Reminder"
        val description = intent.getStringExtra(ReminderManager.EXTRA_REMINDER_DESCRIPTION) ?: ""
        val noteId = intent.getStringExtra(ReminderManager.EXTRA_NOTE_ID) ?: ""

        Log.d("ReminderReceiver", " Reminder triggered: $title")

        val reminderManager = ReminderManager.getInstance(context)
        reminderManager.showReminderNotification(reminderId, title, description, noteId)
    }
}

/**
 * BroadcastReceiver to handle device boot and reschedule alarms
 */
class BootReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (Intent.ACTION_BOOT_COMPLETED == intent.action ||
            Intent.ACTION_MY_PACKAGE_REPLACED == intent.action) {

            Log.d("BootReceiver", " Device booted, rescheduling reminders...")

            val exceptionHandler = CoroutineExceptionHandler { _, exception ->
                Log.e("BootReceiver", "Uncaught exception in BootReceiver scope", exception)
            }
            CoroutineScope(Dispatchers.IO + SupervisorJob() + exceptionHandler).launch {
                val reminderManager = ReminderManager.getInstance(context)
                reminderManager.rescheduleAllReminders()
            }
        }
    }
}

